fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many elements to process
    let limit = n.min(participations.len() as u8);
    
    // Count eligible participants
    let mut eligible_count = 0;
    for i in 0..limit as usize {
        let attendance = participations[i];
        // Check if participant can attend at least k more sessions
        if 5 - attendance >= k {
            eligible_count += 1;
        }
    }
    
    // Maximum number of teams is integer division by 3
    eligible_count / 3
}